<?php $flash=$_SESSION['user_flash']??null;unset($_SESSION['user_flash']); ?>
<section class="mx-auto max-w-4xl space-y-6"><header><p class="text-sm font-semibold uppercase tracking-widest text-primary">Access management</p><h1 class="mt-2 text-3xl font-bold">User Permissions</h1><p class="mt-2 text-zinc-600 dark:text-zinc-300">Set exceptions for <?= e($person['full_name']) ?>. These overrides take precedence over the <?= e(ucfirst($person['role'])) ?> role.</p></header>
    <?php if(is_array($flash)): ?><p role="status" class="rounded-lg border border-green-200 bg-green-50 px-4 py-3 text-sm text-green-800 dark:border-green-900 dark:bg-green-950 dark:text-green-200"><?= e($flash['message']??'') ?></p><?php endif; ?>
    <?php if($person['role']==='admin'): ?><div class="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900 dark:border-amber-900 dark:bg-amber-950 dark:text-amber-200">Admin accounts always retain full access. Per-user overrides are disabled.</div><?php endif; ?>
    <form method="post" action="/users/<?= (int)$person['id'] ?>/permissions" class="rounded-xl bg-white p-5 shadow-sm ring-1 ring-zinc-200 dark:bg-dark-card dark:ring-zinc-800"><input type="hidden" name="_csrf_token" value="<?= e($csrfToken) ?>"><?php $grouped=[];foreach($permissions as $permission)$grouped[$permission['module']][]=$permission; ?>
        <div class="space-y-5"><?php foreach($grouped as $module=>$items): ?><fieldset><legend class="mb-2 text-base font-semibold"><?= e($module) ?></legend><div class="divide-y divide-zinc-100 dark:divide-zinc-800"><?php foreach($items as $permission): $override=$overrides[$permission['permission_key']]??'inherit'; $locked=$person['role']==='admin'||in_array($permission['permission_key'],['users.manage','roles.manage','users.permissions'],true); ?><div class="grid items-center gap-3 py-3 sm:grid-cols-[minmax(0,1fr)_140px_130px]"><div><p class="text-sm font-medium"><?= e($permission['label']) ?></p><code class="text-xs text-zinc-500"><?= e($permission['permission_key']) ?></code></div><label class="text-xs text-zinc-500">Effective: <span class="font-semibold <?= $permission['effective']?'text-green-700 dark:text-green-300':'text-red-600 dark:text-red-300' ?>"><?= $permission['effective']?'Allowed':'Denied' ?></span></label><select name="permission[<?= e($permission['permission_key']) ?>]" <?= $locked?'disabled':'' ?> class="rounded-lg border border-zinc-300 bg-white px-2.5 py-2 text-sm dark:border-zinc-700 dark:bg-zinc-900"><option value="inherit" <?= $override==='inherit'?'selected':'' ?>>Inherit role</option><option value="allow" <?= $override==='allow'?'selected':'' ?>>Allow</option><option value="deny" <?= $override==='deny'?'selected':'' ?>>Deny</option></select></div><?php endforeach; ?></div></fieldset><?php endforeach; ?></div>
        <div class="mt-5 flex justify-between"><a href="/users" class="rounded-lg border border-zinc-300 px-4 py-2.5 text-sm font-semibold dark:border-zinc-700">Back to users</a><?php if($person['role']!=='admin'): ?><button class="rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-white hover:bg-primary-hover">Save user permissions</button><?php endif; ?></div>
    </form>
</section>
